const state={runbooks:[],current:null,user:null,settings:{},csrf:''};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
async function api(path,options={}){const {csrfRetried=false,...requestOptions}=options;const headers={'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(requestOptions.headers||{})};const res=await fetch(path,{...requestOptions,headers});const body=await res.json();if(!res.ok&&res.status===403&&body.error==='Invalid or missing CSRF token'&&!csrfRetried){const sessionResponse=await fetch('/api/auth/me',{headers:{Accept:'application/json'},cache:'no-store'});const sessionBody=await sessionResponse.json();const freshToken=sessionBody?.data?.user?.csrf_token;if(sessionResponse.ok&&freshToken){state.csrf=freshToken;return api(path,{...requestOptions,csrfRetried:true})}}if(!res.ok)throw new Error(body.error||`Request failed (${res.status})`);return body.data??body}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'show error':'show';setTimeout(()=>el.className='',2600)}
function esc(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmt(value){if(!value)return 'Not scheduled';const d=new Date(value);return Number.isNaN(d.valueOf())?esc(value):new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d)}
function chip(status){return `<span class="chip ${esc(status)}">${esc(status)}</span>`}
function formDialog({eyebrow='',title,fields,submitLabel='Save',cancelLabel='Cancel'}){
  return new Promise(resolve=>{
    const dlg=document.createElement('dialog');
    dlg.className='generic-dialog';
    dlg.innerHTML=`<form><div class="modalhead"><div>${eyebrow?`<span class="eyebrow">${esc(eyebrow)}</span>`:''}<h2>${esc(title)}</h2></div><button type="button" class="gd-close" aria-label="Close">×</button></div><div class="gd-fields"></div><div class="modalactions"><button type="button" class="secondary gd-cancel">${esc(cancelLabel)}</button><button class="primary">${esc(submitLabel)}</button></div></form>`;
    const fieldsRoot=dlg.querySelector('.gd-fields');
    fields.forEach(f=>{
      if(f.type==='checkbox'){
        const label=document.createElement('label');label.className='toggle';
        const input=document.createElement('input');input.type='checkbox';input.name=f.name;if(f.value)input.checked=true;
        label.appendChild(input);label.append(f.label);
        if(f.hint){const hint=document.createElement('small');hint.className='muted';hint.textContent=f.hint;label.appendChild(hint)}
        fieldsRoot.appendChild(label);return
      }
      const label=document.createElement('label');
      const span=document.createElement('span');
      span.textContent=f.label;
      label.appendChild(span);
      if(f.hint){const hint=document.createElement('small');hint.className='muted';hint.textContent=f.hint;label.appendChild(hint)}
      let input;
      if(f.type==='textarea'){input=document.createElement('textarea');input.rows=f.rows||3}
      else if(f.type==='select'){input=document.createElement('select');(f.options||[]).forEach(o=>{const opt=document.createElement('option');const [val,text]=Array.isArray(o)?o:[o,o];opt.value=val;opt.textContent=text;input.appendChild(opt)})}
      else{input=document.createElement('input');input.type=f.type||'text'}
      input.name=f.name;
      if(f.value!==undefined&&f.value!==null)input.value=f.value;
      if(f.placeholder)input.placeholder=f.placeholder;
      if(f.required)input.required=true;
      if(f.min!==undefined)input.min=f.min;
      if(f.minlength!==undefined)input.minLength=f.minlength;
      label.appendChild(input);
      fieldsRoot.appendChild(label);
    });
    document.body.appendChild(dlg);
    let result=null;
    const checkboxNames=fields.filter(f=>f.type==='checkbox').map(f=>f.name);
    dlg.querySelector('.gd-close').onclick=()=>dlg.close();
    dlg.querySelector('.gd-cancel').onclick=()=>dlg.close();
    dlg.querySelector('form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;result=Object.fromEntries(new FormData(form));checkboxNames.forEach(name=>{result[name]=form.elements[name].checked});dlg.close()};
    dlg.addEventListener('close',()=>{dlg.remove();resolve(result)});
    dlg.showModal();
    fieldsRoot.querySelector('input,textarea,select')?.focus();
  })
}
function confirmDialog({title,message,confirmLabel='Confirm',cancelLabel='Cancel',danger=false}){
  return new Promise(resolve=>{
    const dlg=document.createElement('dialog');
    dlg.className='generic-dialog generic-confirm-dialog';
    dlg.innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2></div><p>${esc(message)}</p><div class="modalactions"><button type="button" class="secondary gd-cancel">${esc(cancelLabel)}</button><button type="button" class="${danger?'secondary danger':'primary'} gd-ok">${esc(confirmLabel)}</button></div>`;
    document.body.appendChild(dlg);
    let result=false;
    dlg.querySelector('.gd-cancel').onclick=()=>dlg.close();
    dlg.querySelector('.gd-ok').onclick=()=>{result=true;dlg.close()};
    dlg.addEventListener('close',()=>{dlg.remove();resolve(result)});
    dlg.showModal();
  })
}
const genericDialogStyles=`.generic-dialog .gd-fields{display:grid;gap:14px;margin-bottom:4px}.generic-dialog .gd-fields label{display:grid;gap:6px;font-weight:650;font-size:12.5px;color:var(--ink)}.generic-dialog .gd-fields label>span:first-child{color:var(--ink)}.generic-dialog .gd-fields small{font-weight:500;color:var(--muted)}.generic-dialog .gd-close{border:0;background:transparent;color:var(--muted);font-size:18px;line-height:1;cursor:pointer}.generic-confirm-dialog{width:min(420px,calc(100% - 30px))}.generic-confirm-dialog p{color:var(--muted);margin:0}`;
document.head.append(Object.assign(document.createElement('style'),{textContent:genericDialogStyles}));
const VIEW_PATHS={home:'/',runbooks:'/runbooks',templates:'/templates',analytics:'/analytics',admin:'/admin'};
function show(view,opts={}){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${view}`).classList.add('active');$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#crumb').textContent=({home:'Command center',runbooks:'Runbooks',templates:'Templates',analytics:'Analytics',integrations:'ServiceOps',admin:'Administration',detail:'Runbook'}[view]||view);document.querySelector('.shell').classList.remove('menu-open');$('#newRunbook').style.display=(view==='runbooks'||!can('runbooks:edit'))?'none':'';if(view==='admin'){selectAdminCategory('general');if(opts.tool)openAdminTool(opts.tool,{skipHistory:true})}window.scrollTo(0,0);
  // Every top-level view gets a real, bookmarkable/shareable URL (see
  // openRunbook/routeFromLocation for the runbook-detail case, which
  // carries its own id in the path) -- previously this was a pure
  // client-side view switch with no URL change at all, so refreshing or
  // sharing a link always landed back on the dashboard.
  if(!opts.skipHistory&&VIEW_PATHS[view]&&location.pathname!==VIEW_PATHS[view])history.pushState({view},'',VIEW_PATHS[view])}
async function load(){try{const [list,stats]=await Promise.all([api('/api/runbooks'),api('/api/dashboard')]);state.runbooks=list;$('#mRunbooks').textContent=stats.runbooks||0;$('#mLive').textContent=stats.live||0;$('#mProgress').textContent=`${stats.task_completion||0}%`;$('#mComplete').textContent=stats.complete||0;$('#donutValue').textContent=`${stats.task_completion||0}%`;$('.donut').style.setProperty('--p',`${stats.task_completion||0}%`);renderCards();renderTable()}catch(e){toast(e.message,true)}}
function renderCards(){const root=$('#runbookCards');root.innerHTML=state.runbooks.slice(0,3).map(r=>{const p=r.task_count?Math.round(r.done_count*100/r.task_count):0;return `<button type="button" class="runbook-card" data-id="${r.id}" aria-label="Open ${esc(r.name)}, ${esc(r.status)}, ${p}% complete"><span class="cardtop"><h3>${esc(r.name)}</h3>${chip(r.status)}</span><span class="runbook-meta"><span>${esc(r.owner||'Unassigned')}</span><span>•</span><span>${r.task_count} tasks</span><span>•</span><span>${fmt(r.scheduled_at)}</span><span style="margin-left:auto">${p}%</span></span><span class="progress"><i style="width:${p}%"></i></span></button>`}).join('')||'<div class="empty"><p>No runbooks yet.</p></div>';$$('.runbook-card',root).forEach(x=>x.onclick=()=>openRunbook(x.dataset.id))}
let searchResults=null;
async function searchRunbooks(){const q=$('#search')?.value.trim()||'';if(!q){searchResults=null;renderTable();return}try{searchResults=await api(`/api/runbooks?q=${encodeURIComponent(q)}`)}catch(e){searchResults=null}renderTable()}
function renderTable(){const status=$('#statusFilter')?.value||'';const source=searchResults!==null?searchResults:state.runbooks;const items=source.filter(r=>!status||r.status===status);$('#runbookTable').innerHTML=`<div class="trow head"><span>Runbook</span><span>Status</span><span>Owner</span><span>Schedule</span><span>Progress</span></div>`+items.map(r=>{const p=r.task_count?Math.round(r.done_count*100/r.task_count):0;return `<button type="button" class="trow" data-id="${r.id}" aria-label="Open ${esc(r.name)}, ${esc(r.status)}, ${p}% complete"><span><b>${esc(r.name)}</b><small>${r.matched_task?`Matched task: ${esc(r.matched_task)}`:esc(r.serviceops_ticket||'No ServiceOps link')}</small></span>${chip(r.status)}<span>${esc(r.owner||'—')}</span><span>${fmt(r.scheduled_at)}</span><span>${p}%</span></button>`}).join('')||'<div class="empty"><p>No matching runbooks.</p></div>';$$('.trow[data-id]').forEach(x=>x.onclick=()=>openRunbook(x.dataset.id))}
async function openRunbook(id,opts={}){try{activeStream='All';activeOwner='All';activeStatus='All';state.current=await api(`/api/runbooks/${id}`);renderDetail();show('detail',{skipHistory:true});const path=`/runbooks/${id}`;if(!opts.skipHistory&&location.pathname!==path)history.pushState({view:'detail',id},'',path)}catch(e){toast(e.message,true)}}
function routeFromLocation(){
  const path=location.pathname;
  const runbookMatch=path.match(/^\/runbooks\/(\d+)$/);
  if(runbookMatch){openRunbook(runbookMatch[1],{skipHistory:true});return}
  const adminMatch=path.match(/^\/admin\/([A-Za-z]+)$/);
  if(adminMatch){show('admin',{skipHistory:true,tool:adminMatch[1]});return}
  const view=Object.keys(VIEW_PATHS).find(key=>VIEW_PATHS[key]===path);
  show(view||'home',{skipHistory:true})
}
window.addEventListener('popstate',routeFromLocation);
function nextTransitions(status){return {draft:['ready'],ready:['live','draft'],live:['paused','complete'],paused:['live'],complete:[],cancelled:[]}[status]||[]}
function transitionLabel(from,to){if(to==='live')return from==='paused'?'Resume execution':'Start execution';return {ready:'Mark ready',draft:'Move to draft',paused:'Pause execution',complete:'Complete run'}[to]||to}
function renderDetail(){const r=state.current,cp=new Set(r.critical_path);$('#detailContent').innerHTML=`<button class="back" id="backRunbooks">← Back to runbooks</button><div class="detail-head"><div class="detail-title"><div>${chip(r.status)} ${r.serviceops_ticket?`<span class="chip">${esc(r.serviceops_ticket)}</span>`:''}</div><h1>${esc(r.name)}</h1><p>${esc(r.description||'No description')}</p></div><div class="detail-actions">${nextTransitions(r.status).map(s=>`<button class="${s==='live'?'primary':'secondary'} transition" data-status="${s}">${s==='live'?'▶ ':''}${esc(transitionLabel(r.status,s))}</button>`).join('')}<div class="more-menu-wrap"><button type="button" class="secondary more-menu-toggle" aria-haspopup="true" aria-expanded="false">⋯ More</button><div class="more-menu" hidden><button type="button" id="sync">⇄ Sync ServiceOps</button><button type="button" id="openMonitor">🖥 Monitor view</button></div></div></div></div><div class="metrics"><article><span>Progress</span><strong>${r.progress}%</strong><small>${r.tasks.filter(t=>t.status==='complete').length} of ${r.tasks.length} tasks</small></article><article><span>Planned duration</span><strong>${r.duration}<small> min</small></strong><small>Dependency-aware plan</small></article><article><span>Streams</span><strong>${new Set(r.tasks.map(t=>t.stream)).size}</strong><small>Parallel work tracks</small></article><article><span>Owners</span><strong>${new Set(r.tasks.map(t=>t.owner_display||t.owner).filter(Boolean)).size}</strong><small>${r.status==='live'?'Execution controls active':'Safe to edit'}</small></article></div><div class="detail-grid"><article class="panel"><div class="panelhead"><div><h2>Execution plan</h2><p>Purple markers identify the calculated critical path.</p></div><button class="primary" id="addTask">＋ Add task without predecessors</button></div><div class="progress"><i style="width:${r.progress}%"></i></div><div id="tasks">${r.tasks.map((t,i)=>taskHtml(t,i,cp.has(t.id))).join('')||'<div class="empty"><h2>No tasks yet</h2><p>Add the first task to build this plan.</p></div>'}</div></article><aside class="detail-side"><article class="panel sidecard"><h2>Runbook details</h2><div class="kv"><span>Owner</span><b>${esc(r.owner||'Unassigned')}</b></div><div class="kv"><span>Scheduled</span><b>${fmt(r.scheduled_at)}</b></div><div class="kv"><span>ServiceOps</span><b>${esc(r.serviceops_ticket||'Not linked')}</b></div><div class="kv"><span>Updated</span><b>${fmt(r.updated_at)}</b></div></article><article class="panel sidecard"><h2>Conversation</h2>${r.comments.slice(0,4).map(c=>`<div class="comment"><b>${esc(c.author)}</b><p>${esc(c.body)}</p><small>${fmt(c.created_at)}</small></div>`).join('')||'<p class="muted">No comments yet.</p>'}<form class="comment-form" id="commentForm"><input name="body" required placeholder="Add a comment"><button class="primary">Send</button></form></article><article class="panel sidecard"><h2>Immutable history</h2>${r.audit.slice(0,6).map(a=>`<div class="audit"><b>${esc(a.action)}</b> · ${esc(a.detail)}<small>${esc(a.actor)} · ${fmt(a.created_at)}</small></div>`).join('')}</article></aside></div>`;
$('#backRunbooks').onclick=()=>show('runbooks');$('#addTask').onclick=openTaskModal;$('#sync').onclick=syncServiceOps;$('#openMonitor').onclick=openMonitorView;$$('.transition').forEach(b=>b.onclick=()=>transitionRunbook(b.dataset.status));$$('.task-actions button').forEach(b=>b.onclick=()=>transitionTask(b.dataset.id,b.dataset.status));$('#commentForm').onsubmit=addComment}
const STREAM_PALETTE=['#3157e0','#23a8a2','#d9578c','#ec9b39','#27b885','#7353e7','#2947c9','#c0392b'];
function streamColor(name){let h=0;for(const c of String(name||'?'))h=(h*31+c.charCodeAt(0))>>>0;return STREAM_PALETTE[h%STREAM_PALETTE.length]}
function initials(name){return (String(name||'').trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())||'—'}
function depGateBadge(t){
  const n=(t.depends_on||[]).length;
  if(n===0) return '<span class="gate-badge gate-entry" title="Entry point — no dependencies">▶</span>';
  if(n===1) return '<span class="gate-badge gate-seq" title="Runs after 1 task">→</span>';
  return t.dependency_logic==='or'
    ? '<span class="gate-badge gate-or" title="Runs once ANY one of its dependencies finishes (OR)">OR</span>'
    : '<span class="gate-badge gate-and" title="Runs only once ALL of its dependencies finish (AND)">AND</span>';
}
function taskHtml(t,i,isCritical){const actions={pending:t.blocked?[]:['running','skipped'],running:['complete','failed'],failed:['running','skipped'],complete:[],skipped:[]}[t.status];return `<div class="task ${t.blocked&&t.status!=='blocked'?'waiting':''} ${isCritical?'critical':''}"><span class="tasknum">${t.status==='complete'?'✓':i+1}</span><div><h3>${depGateBadge(t)}${esc(t.title)} ${t.blocked&&t.status!=='blocked'?'<span class="chip waiting-chip">waiting</span>':''}</h3><small>${esc(t.stream)} · ${esc(t.owner||'Unassigned')} · ${t.duration} min${t.depends_on.length?` · after #${t.depends_on.join(', #')}`:''}</small></div><div class="task-actions">${actions.map(a=>`<button data-id="${t.id}" data-status="${a}">${a==='running'?window.t('action_start'):a==='complete'?window.t('action_complete'):a==='skipped'?window.t('action_skipped'):esc(a)}</button>`).join('')}</div></div>`}
async function transitionTask(id,status){try{state.current=await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status})});renderDetail();await load();toast(`Task marked ${status}`)}catch(e){toast(e.message,true)}}
async function toggleEscalate(id,on){let reason='';if(on){const r=await formDialog({eyebrow:'ESCALATION',title:'Escalate this task',submitLabel:'Escalate',fields:[{name:'reason',label:'Reason',type:'textarea',hint:'Optional'}]});if(!r)return;reason=r.reason||''}try{state.current=await api(`/api/tasks/${id}/escalate`,{method:'POST',body:JSON.stringify({escalated:on,reason})});renderDetail();toast(on?'Task escalated':'Escalation cleared')}catch(e){toast(e.message,true)}}
async function toggleIncident(id,on){let reason='';if(on){const r=await formDialog({eyebrow:'INCIDENT',title:'Flag this task as incident-causing',submitLabel:'Flag incident',fields:[{name:'reason',label:'What happened?',type:'textarea',hint:'Optional'}]});if(!r)return;reason=r.reason||''}try{state.current=await api(`/api/tasks/${id}/incident`,{method:'POST',body:JSON.stringify({incident:on,reason})});renderDetail();toast(on?'Task flagged as incident-causing':'Incident flag cleared')}catch(e){toast(e.message,true)}}
async function transitionRunbook(status){try{state.current=await api(`/api/runbooks/${state.current.id}/transition`,{method:'POST',body:JSON.stringify({status})});renderDetail();await load();toast(`Runbook moved to ${status}`)}catch(e){toast(e.message,true)}}
async function addComment(e){e.preventDefault();const data=new FormData(e.currentTarget);try{state.current=await api(`/api/runbooks/${state.current.id}/comments`,{method:'POST',body:JSON.stringify({body:data.get('body')})});renderDetail();toast('Comment added')}catch(err){toast(err.message,true)}}
async function syncServiceOps(){try{state.current=await api(`/api/runbooks/${state.current.id}/serviceops-sync`,{method:'POST',body:'{}'});renderDetail();toast(`Synced ${state.current.serviceops_ticket}`)}catch(e){toast(e.message,true)}}
function orderFoldersByDepth(folders){const byParent={};folders.forEach(f=>{const key=f.parent_folder_id||0;(byParent[key]=byParent[key]||[]).push(f)});const ordered=[];const walk=(parentId,depth)=>{(byParent[parentId]||[]).forEach(f=>{ordered.push({...f,depth});walk(f.id,depth+1)})};walk(0,0);return ordered}
async function openModal(name=''){const m=$('#runbookModal');$('#runbookForm').reset();if(name)$('#runbookForm [name=name]').value=name;try{const [folders,types]=await Promise.all([api('/api/folders'),api('/api/runbook-types')]);const folderSelect=$('#runbookForm [name=folder_id]');folderSelect.innerHTML='<option value="">No folder</option>'+orderFoldersByDepth(folders).map(f=>`<option value="${f.id}">${'— '.repeat(f.depth)}${esc(f.name)}</option>`).join('');const typeSelect=$('#runbookForm [name=runbook_type_id]');typeSelect.innerHTML='<option value="">No type</option>'+types.map(t=>`<option value="${t.id}">${t.icon} ${esc(t.name)}</option>`).join('')}catch(e){}m.showModal()}
function openTaskModal(){const m=$('#taskModal'),form=$('#taskForm');form.reset();form.runbook_id.value=state.current.id;form.depends_on.innerHTML=state.current.tasks.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');m.showModal()}
$('#runbookForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const created=await api('/api/runbooks',{method:'POST',body:JSON.stringify(data)});$('#runbookModal').close();await load();openRunbook(created.id);toast('Runbook created')}catch(err){toast(err.message,true)}};
$('#taskForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.depends_on=[...form.depends_on.selectedOptions].map(o=>Number(o.value));data.duration=Number(data.duration);try{state.current=await api(`/api/runbooks/${data.runbook_id}/tasks`,{method:'POST',body:JSON.stringify(data)});$('#taskModal').close();renderDetail();await load();toast('Task added')}catch(err){toast(err.message,true)}};
$$('.nav,[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('#newRunbook').onclick=()=>openModal();$$('.new-trigger').forEach(b=>b.onclick=()=>openModal());$$('.template-use').forEach(b=>b.onclick=()=>openModal(b.dataset.name));$$('.close').forEach(b=>b.onclick=()=>$('#runbookModal').close());$$('.close-task').forEach(b=>b.onclick=()=>$('#taskModal').close());$('#refresh').onclick=load;let searchDebounce;$('#search').oninput=()=>{clearTimeout(searchDebounce);searchDebounce=setTimeout(searchRunbooks,220)};$('#statusFilter').onchange=renderTable;
async function loadSavedViews(){try{const views=await api('/api/saved-views');const select=$('#savedViewSelect');select.innerHTML='<option value="">Saved views…</option>'+views.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('');select.dataset.views=JSON.stringify(views)}catch(e){}}
$('#savedViewSelect').onchange=e=>{if(!e.target.value)return;const views=JSON.parse($('#savedViewSelect').dataset.views||'[]');const view=views.find(v=>String(v.id)===e.target.value);if(!view)return;$('#search').value=view.filters.q||'';$('#statusFilter').value=view.filters.status||'';if(view.filters.q)searchRunbooks();else{searchResults=null;renderTable()}};
$('#saveViewBtn').onclick=async()=>{const r=await formDialog({eyebrow:'RUNBOOKS',title:'Save this view',submitLabel:'Save view',fields:[{name:'name',label:'View name',required:true,placeholder:'e.g. My live runbooks'}]});if(!r||!r.name)return;try{await api('/api/saved-views',{method:'POST',body:JSON.stringify({name:r.name,filters:{q:$('#search').value.trim(),status:$('#statusFilter').value}})});await loadSavedViews();toast('View saved')}catch(e){toast(e.message,true)}};$('#menu').onclick=()=>$('.shell').classList.toggle('menu-open');
document.addEventListener('click',e=>{
  const toggle=e.target.closest('.more-menu-toggle');
  const openMenu=$('.more-menu-wrap.open .more-menu');
  if(toggle){const wrap=toggle.closest('.more-menu-wrap');const opening=!wrap.classList.contains('open');$$('.more-menu-wrap.open').forEach(w=>{w.classList.remove('open');w.querySelector('.more-menu').hidden=true;w.querySelector('.more-menu-toggle').setAttribute('aria-expanded','false')});if(opening){wrap.classList.add('open');wrap.querySelector('.more-menu').hidden=false;toggle.setAttribute('aria-expanded','true')}return}
  if(openMenu&&!e.target.closest('.more-menu-wrap')){$$('.more-menu-wrap.open').forEach(w=>{w.classList.remove('open');w.querySelector('.more-menu').hidden=true;w.querySelector('.more-menu-toggle').setAttribute('aria-expanded','false')})}
  if(e.target.closest('.more-menu')&&e.target.tagName==='BUTTON'){$$('.more-menu-wrap.open').forEach(w=>{w.classList.remove('open');w.querySelector('.more-menu').hidden=true;w.querySelector('.more-menu-toggle').setAttribute('aria-expanded','false')})}
});
