renderDetail=function(){baseRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot)return;$$('.task',taskRoot).forEach((el,i)=>{el.classList.add(`status-${r.tasks[i]?.status||'pending'}`)});const owners=[...new Set(r.tasks.map(t=>t.owner_display||t.owner||'Unassigned'))].sort();const statuses=[...new Set(r.tasks.map(t=>t.status))].sort();const applyFilters=()=>$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];const visible=(activeStream==='All'||t.stream===activeStream)&&(activeOwner==='All'||(t.owner_display||t.owner||'Unassigned')===activeOwner)&&(activeStatus==='All'||t.status===activeStatus);el.style.display=visible?'':'none'});const controls=document.createElement('div');controls.innerHTML=`<div class="plan-toolbar"><div class="view-switch"><button class="active" data-mode="timeline">☷ List</button><button data-mode="map">⌘ Nodemap</button></div><label class="plan-select-all"><input type="checkbox" id="planSelectAll"> Select all</label><span class="plan-task-count">${r.tasks.length} tasks</span></div><div class="plan-filter-rail"><div class="filter-section"><h4>Stream</h4><div class="filter-list"><button class="filter-pill ${activeStream==='All'?'active':''}" data-stream="All"><span>All</span><b>${r.tasks.length}</b></button>${r.streams.map(s=>`<span class="filter-pill-group"><button class="filter-pill ${activeStream===s.name?'active':''}" data-stream="${esc(s.name)}" title="Filter by ${esc(s.name)}"><span>${esc(s.name)}</span><b>${s.task_count}</b></button><button class="stream-edit" data-stream-rename="${s.id}" data-stream-name="${esc(s.name)}" aria-label="Rename or delete ${esc(s.name)} stream">✎</button></span>`).join('')}<button class="filter-pill stream-add" data-stream-add title="Add a stream">＋ Add stream</button></div></div><div class="filter-section"><h4>Owner</h4><select data-owner-filter><option value="All">All owners</option>${owners.map(o=>`<option value="${esc(o)}" ${activeOwner===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div class="filter-section"><h4>Status</h4><select data-status-filter><option value="All">All statuses</option>${statuses.map(s=>`<option value="${esc(s)}" ${activeStatus===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div></div>`;const planToolbar=controls.querySelector('.plan-toolbar'),planRail=controls.querySelector('.plan-filter-rail'),planBody=document.createElement('div');planBody.className='plan-body';taskRoot.parentNode.insertBefore(planToolbar,taskRoot);const selectAllBox=$('#planSelectAll',planToolbar);if(selectAllBox)selectAllBox.onchange=()=>{selectAllBox.checked=false;bulkEditTasks()};taskRoot.parentNode.insertBefore(planBody,taskRoot);planBody.appendChild(planRail);planBody.appendChild(taskRoot);const ownerSelect=$('[data-owner-filter]',planRail);if(ownerSelect)ownerSelect.onchange=()=>{activeOwner=ownerSelect.value;applyFilters()};const statusSelect=$('[data-status-filter]',planRail);if(statusSelect)statusSelect.onchange=()=>{activeStatus=statusSelect.value;applyFilters()};$$('[data-stream]',planRail).forEach(b=>{b.onclick=()=>{activeStream=b.dataset.stream;$$('[data-stream]',planRail).forEach(x=>x.classList.toggle('active',x===b));applyFilters()}});$$('[data-stream-rename]',planRail).forEach(b=>{b.onclick=async()=>{const next=await formDialog({eyebrow:'STREAM',title:'Rename stream',submitLabel:'Save',fields:[{name:'name',label:'Stream name',value:b.dataset.streamName,required:false,hint:'Clear the field and save to delete an empty stream'}]});if(!next)return;const name=(next.name||'').trim();if(name===b.dataset.streamName)return;try{state.current=name?await api(`/api/streams/${b.dataset.streamRename}`,{method:'PATCH',body:JSON.stringify({name})}):await api(`/api/streams/${b.dataset.streamRename}`,{method:'DELETE'});renderDetail()}catch(e){toast(e.message,true)}}});const addStream=$('[data-stream-add]',planRail);if(addStream)addStream.onclick=async()=>{const r2=await formDialog({eyebrow:'STREAM',title:'Add a stream',submitLabel:'Add stream',fields:[{name:'name',label:'Stream name',required:true,placeholder:'e.g. Database'}]});if(!r2||!r2.name)return;try{state.current=await api(`/api/runbooks/${r.id}/streams`,{method:'POST',body:JSON.stringify({name:r2.name})});renderDetail()}catch(e){toast(e.message,true)}};$$('[data-mode]',planToolbar).forEach(b=>b.onclick=()=>{$$('[data-mode]',planToolbar).forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.mode==='timeline'){taskRoot.innerHTML=r.tasks.map((t,i)=>taskHtml(t,i,new Set(r.critical_path).has(t.id))).join('');$$('.task',taskRoot).forEach((el,i)=>el.classList.add(`status-${r.tasks[i].status}`));$$('.task-actions button',taskRoot).forEach(x=>x.onclick=()=>transitionTask(x.dataset.id,x.dataset.status))}else{const byId={};r.tasks.forEach(t=>byId[t.id]=t);const level={};const levelOf=id=>{if(level[id]!==undefined)return level[id];const t=byId[id];const l=t&&t.depends_on.length?1+Math.max(...t.depends_on.map(levelOf)):0;level[id]=l;return l};r.tasks.forEach(t=>levelOf(t.id));const maxLevel=Math.max(0,...r.tasks.map(t=>level[t.id]));const critical=new Set(r.critical_path||[]);const cols=[];for(let l=0;l<=maxLevel;l++){const nums={};r.tasks.forEach((t,i)=>nums[t.id]=i+1);const colTasks=r.tasks.filter(t=>level[t.id]===l);cols.push(`<div class="node-col"><span class="node-col-label">Step ${l+1}</span>${colTasks.map(t=>`<div class="node ${esc(t.status)} ${critical.has(t.id)?'critical':''}"><em>${esc(t.stream)}</em><b>${depGateBadge(t)}#${nums[t.id]} ${esc(t.title)}</b><span>${esc(t.owner||'Unassigned')} · ${t.duration} min</span><small>${t.depends_on.length?'Depends on task'+(t.depends_on.length>1?'s ':' ')+t.depends_on.join(', '):'Entry point'} · ${esc(t.status)}</small>${critical.has(t.id)?'<span class="node-critical-badge">Critical path</span>':''}</div>`).join('')}</div>`)}taskRoot.innerHTML=`<div class="node-map">${cols.join('')}</div>`}});applyFilters()};
