const guideRenderDetail=renderDetail;renderDetail=function(){guideRenderDetail();const side=$('.detail-side');if(!side)return;const card=document.createElement('article');card.className='panel sidecard team-card';card.innerHTML=`<div class="panelhead"><div><h2>Runbook teams</h2><p>Assigned executors</p></div></div>${(state.current.teams||[]).map(t=>`<div class="team-line"><div><b>${esc(t.name)}</b><small>${t.member_count} member${t.member_count===1?'':'s'}</small></div><span>↗</span></div>`).join('')||'<p class="muted">No teams configured.</p>'}${can('runbooks:edit')?'<button class="secondary" id="createTeam" style="margin-top:12px">＋ Create team</button>':''}`;side.prepend(card);if($('#createTeam'))$('#createTeam').onclick=showTeamCreator};
async function showTeamCreator(){try{const options=await api(`/api/runbooks/${state.current.id}/assignment-options`);const dlg=document.createElement('dialog');dlg.className='generic-dialog';dlg.innerHTML=`<form><div class="modalhead"><div><span class="eyebrow">RUNBOOK TEAMS</span><h2>Create a team</h2></div><button type="button" class="gd-close" aria-label="Close">×</button></div><div class="gd-fields"><label><span>Team name</span><input name="name" required></label><label><span>Members</span><div class="member-picker">${options.users.map(u=>`<label><input type="checkbox" name="user_id" value="${u.id}">${esc(u.display_name)}</label>`).join('')||'<p class="muted">No workspace users available.</p>'}</div></label></div><div class="modalactions"><button type="button" class="secondary gd-cancel">Cancel</button><button class="primary">Create team</button></div></form>`;document.body.append(dlg);let result=null;dlg.querySelector('.gd-close').onclick=()=>dlg.close();dlg.querySelector('.gd-cancel').onclick=()=>dlg.close();dlg.querySelector('form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;result={name:form.name.value,user_ids:[...form.querySelectorAll('[name=user_id]:checked')].map(x=>Number(x.value))};dlg.close()};await new Promise(resolve=>{dlg.addEventListener('close',()=>{dlg.remove();resolve()});dlg.showModal()});if(!result||!result.name)return;await api(`/api/runbooks/${state.current.id}/teams`,{method:'POST',body:JSON.stringify(result)});state.current=await api(`/api/runbooks/${state.current.id}`);renderDetail();toast('Runbook team created')}catch(e){toast(e.message,true)}}
