const activity=[];let unread=0;const drawer=document.createElement('section');drawer.id='activityNotifications';drawer.className='notification-drawer';drawer.setAttribute('aria-label','Activity notifications');drawer.hidden=true;drawer.innerHTML='<div class="notification-head"><h2>Live activity</h2><button id="clearActivity">Clear</button></div><div class="notification-list"><div class="notification-empty">Activity from your workspace will appear here.</div></div>';document.body.append(drawer);const bell=$('#notifBell');bell.setAttribute('aria-expanded','false');bell.setAttribute('aria-controls',drawer.id);const count=document.createElement('span');count.className='unread-count';count.hidden=true;bell.append(count);bell.onclick=()=>{const open=!drawer.classList.contains('open');drawer.hidden=false;drawer.classList.toggle('open',open);if(!open)drawer.hidden=true;bell.setAttribute('aria-expanded',String(open));unread=0;count.hidden=true};$('#clearActivity').onclick=()=>{activity.length=0;renderActivity()};
