const serviceOpsRenderDetail=renderDetail;renderDetail=function(){serviceOpsRenderDetail();const r=state.current;if(!r?.serviceops_ticket||!$('.detail-side'))return;const card=document.createElement('article');card.className='panel sidecard';card.innerHTML=`<div class="connection-head" style="padding:0 0 13px"><span class="provider-icon">SO</span><div><h2>ServiceOps record</h2><p>REST API v1 · last sync ${fmt(r.serviceops_synced_at)}</p></div></div><div class="kv"><span>Number</span><b>${esc(r.serviceops_ticket)}</b></div><div class="kv"><span>Type</span><b>${esc(r.serviceops_type||'—')}</b></div><div class="kv"><span>State</span><b>${esc(r.serviceops_state||'Not synchronized')}</b></div><div class="kv"><span>Priority</span><b>${esc(r.serviceops_priority||'—')}</b></div>${r.serviceops_title?`<p class="task-description">${esc(r.serviceops_title)}</p>`:''}<small class="muted">Request correlation: ${esc(r.serviceops_request_id||'—')}</small>`;$('.detail-side').prepend(card)};
const templateStyles=`.runbook-tags{display:flex;gap:6px;margin-top:4px}.type-tag{font-size:10px;color:var(--muted);background:#f4f3fb;border-radius:20px;padding:2px 8px}.template-category{margin-bottom:26px}.template-category h2{font-size:15px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:0 0 12px}.template-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:18px}.template-actions{display:flex;gap:8px;align-items:center;margin-top:14px}.template-actions .icon{margin-left:auto;background:transparent;border:1px solid var(--line);border-radius:7px;padding:6px 9px}`;document.head.append(Object.assign(document.createElement('style'),{textContent:templateStyles}));
async function createApiToken(){const r=await formDialog({eyebrow:'API TOKENS',title:'Create an API token',submitLabel:'Create token',fields:[{name:'name',label:'Token name',required:true,placeholder:'e.g. CI pipeline'},{name:'scopes',label:'Scopes',value:'runbooks:read',hint:'Comma-separated: runbooks:read, runbooks:write, scim:provision'}]});if(!r||!r.name)return;const scopes=(r.scopes||'').split(',').map(s=>s.trim()).filter(Boolean);if(!scopes.length)return;try{const result=await api('/api/admin/api-tokens',{method:'POST',body:JSON.stringify({name:r.name,scopes})});await formDialog({eyebrow:'COPY THIS NOW',title:'API token created',submitLabel:'Done',fields:[{name:'token',label:'This will not be shown again',value:result.token}]});loadAdminPanel('apiTokens')}catch(e){toast(e.message,true)}}
async function revokeApiToken(id){if(!await confirmDialog({title:'Revoke this API token?',message:'Any integration using it will immediately lose access.',confirmLabel:'Revoke token',danger:true}))return;try{await api(`/api/admin/api-tokens/${id}/revoke`,{method:'POST',body:'{}'});loadAdminPanel('apiTokens')}catch(e){toast(e.message,true)}}
async function createWebhook(){let available=[];try{const res=await fetch('/api/admin/webhooks');const body=await res.json();available=body.available_events||[]}catch(e){}const r=await formDialog({eyebrow:'WEBHOOKS',title:'Create a webhook',submitLabel:'Create webhook',fields:[{name:'name',label:'Webhook name',required:true,placeholder:'e.g. Deploy pipeline'},{name:'provider',label:'Destination type',type:'select',options:[['generic','Generic (signed JSON)'],['slack','Slack'],['teams','Microsoft Teams']]},{name:'url',label:'Destination URL',required:true,placeholder:'https://...'},{name:'events',label:'Events',hint:`Comma-separated, or leave blank for every event ("*"). Available: ${available.join(', ')||'—'}`}]});if(!r||!r.name||!r.url)return;const provider=['generic','slack','teams'].includes(r.provider)?r.provider:'generic';let events=['*'];if(r.events&&r.events.trim()){const picked=r.events.split(',').map(s=>s.trim()).filter(s=>available.includes(s));if(picked.length)events=picked}try{const result=await api('/api/admin/webhooks',{method:'POST',body:JSON.stringify({name:r.name,url:r.url,provider,events})});if(result.secret){await formDialog({eyebrow:'COPY THIS NOW',title:'Webhook created',submitLabel:'Done',fields:[{name:'secret',label:'Signing secret — this will not be shown again',value:result.secret,hint:'Verify deliveries with header X-FlowOps-Signature: sha256=<HMAC-SHA256 of the body, using this secret>'}]})}else{toast(`${provider[0].toUpperCase()+provider.slice(1)} webhook created. No separate secret — the destination URL itself is the credential.`)}loadAdminPanel('webhooks')}catch(e){toast(e.message,true)}}
async function testWebhook(id){try{await api(`/api/admin/webhooks/${id}/test`,{method:'POST',body:'{}'});toast('Test delivery sent');loadAdminPanel('webhooks')}catch(e){toast(e.message,true)}}
async function deleteWebhook(id){if(!await confirmDialog({title:'Delete this webhook?',message:'Event delivery to this destination will stop immediately.',confirmLabel:'Delete webhook',danger:true}))return;try{await api(`/api/admin/webhooks/${id}`,{method:'DELETE'});loadAdminPanel('webhooks')}catch(e){toast(e.message,true)}}
const tokenLoadAdminPanel=loadAdminPanel;loadAdminPanel=async function(name){if(name==='apiTokens'){try{const tokens=await api('/api/admin/api-tokens');$('#apiTokenAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>API tokens</h2><p>Scoped bearer tokens for external automation. Secrets are shown once, at creation.</p></div><button class="primary" id="createApiToken">＋ New token</button></div>${tokens.map(t=>`<div class="admin-list-row"><div><b>${esc(t.name)}</b><small>${t.scopes.map(esc).join(', ')}</small></div><span>${t.last_used_at?'Used '+fmt(t.last_used_at):'Never used'}</span><span>${t.revoked_at?'Revoked':'Active'}</span>${t.revoked_at?'':`<button class="secondary danger" data-token-revoke="${t.id}">Revoke</button>`}</div>`).join('')||'<p class="muted">No API tokens yet.</p>'}</div>`;$('#createApiToken').onclick=createApiToken;$$('[data-token-revoke]').forEach(b=>b.onclick=()=>revokeApiToken(b.dataset.tokenRevoke))}catch(e){toast(e.message,true)}return}if(name==='webhooks'){try{const hooks=await api('/api/admin/webhooks');$('#webhookAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Outbound webhooks</h2><p>Signed HTTP callbacks on runbook and task state changes.</p></div><button class="primary" id="createWebhook">＋ New webhook</button></div>${hooks.map(h=>{const last=h.recent_deliveries[0];return `<div class="admin-list-row"><div><b>${esc(h.name)}</b><small>${h.provider!=="generic"?h.provider+" · ":""}${esc(h.url)} · ${h.events.includes('*')?'all events':h.events.length+' event'+(h.events.length===1?'':'s')}</small></div><span>${last?(last.success?'✓ Delivered':'✗ '+esc(last.error||'Failed')):'No deliveries yet'}</span><span>${h.active?'Active':'Paused'}</span><div class="inline-actions"><button class="secondary" data-webhook-test="${h.id}">Send test</button><button class="secondary danger" data-webhook-delete="${h.id}">Delete</button></div></div>`}).join('')||'<p class="muted">No webhooks yet.</p>'}</div>`;$('#createWebhook').onclick=createWebhook;$$('[data-webhook-test]').forEach(b=>b.onclick=()=>testWebhook(b.dataset.webhookTest));$$('[data-webhook-delete]').forEach(b=>b.onclick=()=>deleteWebhook(b.dataset.webhookDelete))}catch(e){toast(e.message,true)}return}return tokenLoadAdminPanel(name)};
async function loadTemplates(){try{const templates=await api('/api/templates');const byCategory={};templates.forEach(t=>{(byCategory[t.category]=byCategory[t.category]||[]).push(t)});const icons=['↗','⌁','✦','◈','⌘','◇'];let iconIndex=0;$('#templateGrid').innerHTML=Object.keys(byCategory).length?Object.entries(byCategory).map(([category,items])=>`<div class="template-category"><h2>${esc(category)}</h2><div class="template-row">${items.map(t=>{const icon=icons[iconIndex++%icons.length];return `<article><span class="templateicon">${icon}</span><h3>${esc(t.name)}</h3><p>${esc(t.description||`${t.task_count} tasks`)}</p><div class="template-actions"><button class="secondary" data-template-use="${t.id}">Use template</button><button class="icon" data-template-delete="${t.id}" aria-label="Delete ${esc(t.name)} template">🗑</button></div></article>`}).join('')}</div></div>`).join(''):'<div class="empty panel"><span>◇</span><h2>No templates yet</h2><p>Open a runbook and choose "Save as template" to create one.</p></div>';$$('[data-template-use]',$('#templateGrid')).forEach(b=>b.onclick=async()=>{const r=await formDialog({eyebrow:'NEW OPERATION',title:'Name this runbook',submitLabel:'Create runbook',fields:[{name:'name',label:'Runbook name',required:true}]});if(!r||!r.name)return;try{const created=await api(`/api/templates/${b.dataset.templateUse}/use`,{method:'POST',body:JSON.stringify({name:r.name})});await load();openRunbook(created.id);toast('Runbook created from template')}catch(e){toast(e.message,true)}});$$('[data-template-delete]',$('#templateGrid')).forEach(b=>b.onclick=async()=>{if(!await confirmDialog({title:'Delete this template?',message:'This does not affect runbooks already created from it.',confirmLabel:'Delete template',danger:true}))return;try{await api(`/api/templates/${b.dataset.templateDelete}`,{method:'DELETE'});loadTemplates();toast('Template deleted')}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
const templatesShow=show;show=function(view,opts={}){templatesShow(view,opts);if(view==='templates')loadTemplates()};
const foldersRenderTable=renderTable;renderTable=function(){foldersRenderTable();$$('.trow[data-id]').forEach(el=>{const r=state.runbooks.find(x=>String(x.id)===el.dataset.id);if(!r)return;const nameCell=el.querySelector('div');if(!nameCell||nameCell.querySelector('.runbook-tags'))return;const tags=[];if(r.runbook_type_name)tags.push(`<span class="type-tag" style="color:${esc(r.runbook_type_color||'#3157e0')}">${r.runbook_type_icon||'◇'} ${esc(r.runbook_type_name)}</span>`);if(r.folder_name)tags.push(`<span class="type-tag">📁 ${esc(r.folder_name)}</span>`);if(tags.length)nameCell.insertAdjacentHTML('beforeend',`<div class="runbook-tags">${tags.join('')}</div>`)})};
async function saveAsTemplate(){const r=await formDialog({eyebrow:'STANDARDIZE',title:'Save as template',submitLabel:'Save template',fields:[{name:'name',label:'Template name',value:`${state.current.name} template`,required:true},{name:'category',label:'Category',value:'General',placeholder:'e.g. Release, Incident Response, Disaster Recovery, Migration'}]});if(!r||!r.name)return;try{await api(`/api/runbooks/${state.current.id}/save-as-template`,{method:'POST',body:JSON.stringify({name:r.name,category:r.category||'General'})});toast('Saved as template')}catch(e){toast(e.message,true)}}
async function duplicateRunbook(){try{const created=await api(`/api/runbooks/${state.current.id}/duplicate`,{method:'POST',body:'{}'});await load();openRunbook(created.id);toast('Runbook duplicated')}catch(e){toast(e.message,true)}}
