function openMonitorView(){window.open(`/monitor.html?rid=${state.current.id}`,'_blank','noopener')}
async function deleteRunbook(){const r=state.current;const confirmation=await formDialog({eyebrow:'DANGER ZONE',title:`Delete "${r.name}"?`,submitLabel:'Delete runbook',fields:[{name:'confirm_name',label:`Type the runbook name to confirm`,hint:'This permanently removes its tasks, streams, and comments. Audit history is kept. This cannot be undone.',placeholder:r.name,required:true}]});if(!confirmation)return;if(confirmation.confirm_name.trim()!==r.name)return toast('Name did not match -- runbook was not deleted',true);try{await api(`/api/runbooks/${r.id}`,{method:'DELETE'});toast('Runbook deleted');show('runbooks');await load()}catch(e){toast(e.message,true)}}
const lifecycleRenderDetail=renderDetail;renderDetail=function(){lifecycleRenderDetail();const r=state.current,menu=$('.more-menu');if(!menu)return;const hasDelete=can('admin:access')&&r.status!=='live';menu.insertAdjacentHTML('beforeend',`<button type="button" id="saveAsTemplate">▤ Save as template</button><button type="button" id="duplicateRunbook">⎘ Duplicate</button>${r.status==='complete'&&!r.archived?'<button type="button" id="archiveRunbook">🗄 Archive</button>':''}${hasDelete?'<hr><button type="button" class="danger" id="deleteRunbook">🗑 Delete runbook</button>':''}`);$('#saveAsTemplate').onclick=saveAsTemplate;$('#duplicateRunbook').onclick=duplicateRunbook;if($('#archiveRunbook'))$('#archiveRunbook').onclick=archiveRunbook;if($('#deleteRunbook'))$('#deleteRunbook').onclick=deleteRunbook};
const csvRenderDetail=renderDetail;renderDetail=function(){csvRenderDetail();const r=state.current,menu=$('.more-menu');if(!menu||!can('runbooks:edit'))return;menu.insertAdjacentHTML('beforeend','<button type="button" id="exportTasksCsv">⇩ Export CSV</button><button type="button" id="importTasksCsv">⇧ Import CSV</button><input type="file" id="importTasksCsvFile" accept=".csv,text/csv" hidden>');$('#exportTasksCsv').onclick=()=>{window.open(`/api/runbooks/${r.id}/tasks.csv`,'_blank')};$('#importTasksCsv').onclick=()=>$('#importTasksCsvFile').click();$('#importTasksCsvFile').onchange=async(e)=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();const result=await api(`/api/runbooks/${r.id}/tasks-import`,{method:'POST',body:JSON.stringify({csv:text})});state.current=result;toast(`Imported tasks from CSV`);renderDetail()}catch(err){toast(err.message,true)}e.target.value=''}};
async function createWorkspaceManagerGrant(){const users=await api('/api/admin/users');const workspaces=await api('/api/workspaces');const r=await formDialog({eyebrow:'SCOPED ROLES',title:'Grant Workspace Manager',submitLabel:'Grant',fields:[{name:'user',label:'User',type:'select',options:users.map(u=>[u.username,`${u.display_name} (${u.username})`])},{name:'workspace',label:'Workspace',type:'select',options:workspaces.map(w=>[String(w.id),w.name])}]});if(!r)return;const user=users.find(u=>u.username===r.user);if(!user)return toast('User not found',true);try{await api('/api/admin/workspace-managers',{method:'POST',body:JSON.stringify({user_id:user.id,workspace_id:Number(r.workspace)})});loadAdminPanel('scopedRoles');toast('Workspace Manager grant added')}catch(e){toast(e.message,true)}}
