const scopedRolesLoadAdminPanel=loadAdminPanel;loadAdminPanel=async function(name){if(name==='scopedRoles'){try{const grants=await api('/api/admin/scoped-role-grants');$('#scopedRoleAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Workspace Managers</h2><p>Editor-equivalent rights, scoped to one workspace.</p></div><button class="primary" data-grant-wm>＋ Grant</button></div>${grants.workspace_managers.map(g=>`<div class="admin-list-row"><div><b>${esc(g.display_name)}</b></div><span>${esc(g.workspace_name)}</span><button class="secondary danger" data-revoke-wm="${g.user_id}:${g.workspace_id}">Revoke</button></div>`).join('')||'<p class="muted">No Workspace Manager grants yet.</p>'}</div><div class="panel"><div class="panelhead"><div><h2>Folder Creators</h2><p>Can create runbooks only within a granted folder.</p></div><button class="primary" data-grant-fc>＋ Grant</button></div>${grants.folder_creators.map(g=>`<div class="admin-list-row"><div><b>${esc(g.display_name)}</b></div><span>${esc(g.folder_name)}</span><button class="secondary danger" data-revoke-fc="${g.user_id}:${g.folder_id}">Revoke</button></div>`).join('')||'<p class="muted">No Folder Creator grants yet.</p>'}</div><div class="panel"><div class="panelhead"><div><h2>Stream Editors</h2><p>Can edit streams and tasks only within a granted runbook.</p></div><button class="primary" data-grant-se>＋ Grant</button></div>${grants.stream_editors.map(g=>`<div class="admin-list-row"><div><b>${esc(g.display_name)}</b></div><span>${esc(g.runbook_name)}</span><button class="secondary danger" data-revoke-se="${g.user_id}:${g.runbook_id}">Revoke</button></div>`).join('')||'<p class="muted">No Stream Editor grants yet.</p>'}</div>`;$('[data-grant-wm]').onclick=createWorkspaceManagerGrant;$('[data-grant-fc]').onclick=createFolderCreatorGrant;$('[data-grant-se]').onclick=createStreamEditorGrant;$$('[data-revoke-wm]').forEach(b=>{const[u,w]=b.dataset.revokeWm.split(':');b.onclick=()=>revokeWorkspaceManagerGrant(u,w)});$$('[data-revoke-fc]').forEach(b=>{const[u,f]=b.dataset.revokeFc.split(':');b.onclick=()=>revokeFolderCreatorGrant(u,f)});$$('[data-revoke-se]').forEach(b=>{const[u,r]=b.dataset.revokeSe.split(':');b.onclick=()=>revokeStreamEditorGrant(u,r)})}catch(e){toast(e.message,true)}return}return scopedRolesLoadAdminPanel(name)};
