function pickTasksDialog({eyebrow,title,tasks,submitLabel='Continue',extraFields=[]}){
  return new Promise(resolve=>{
    const dlg=document.createElement('dialog');dlg.className='generic-dialog';
    dlg.innerHTML=`<form><div class="modalhead"><div><span class="eyebrow">${esc(eyebrow)}</span><h2>${esc(title)}</h2></div><button type="button" class="gd-close" aria-label="Close">×</button></div><div class="gd-fields"><label><span>Tasks</span><div class="member-picker">${tasks.map(t=>`<label><input type="checkbox" name="task_id" value="${t.id}">${esc(t.title)}</label>`).join('')}</div></label><div class="gd-extra"></div></div><div class="modalactions"><button type="button" class="secondary gd-cancel">Cancel</button><button class="primary">${esc(submitLabel)}</button></div></form>`;
    const extraRoot=dlg.querySelector('.gd-extra');
    extraFields.forEach(f=>{
      const label=document.createElement('label');const span=document.createElement('span');span.textContent=f.label;label.appendChild(span);
      if(f.hint){const hint=document.createElement('small');hint.className='muted';hint.textContent=f.hint;label.appendChild(hint)}
      const input=document.createElement('input');input.type=f.type||'text';input.name=f.name;if(f.placeholder)input.placeholder=f.placeholder;
      label.appendChild(input);extraRoot.appendChild(label);
    });
    document.body.append(dlg);let result=null;
    dlg.querySelector('.gd-close').onclick=()=>dlg.close();
    dlg.querySelector('.gd-cancel').onclick=()=>dlg.close();
    dlg.querySelector('form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;const task_ids=[...form.querySelectorAll('[name=task_id]:checked')].map(x=>Number(x.value));const extra=Object.fromEntries(extraFields.map(f=>[f.name,form.elements[f.name]?.value||'']));result={task_ids,...extra};dlg.close()};
    dlg.addEventListener('close',()=>{dlg.remove();resolve(result)});
    dlg.showModal();
  })
}
