const stateChipsRenderDetail=renderDetail;renderDetail=function(){stateChipsRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot||!r||!can('runbooks:execute'))return;$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];if(!t)return;const h3=el.querySelector('h3');if(!h3)return;el.classList.toggle('escalated',!!t.escalated);el.classList.toggle('incident',!!t.incident);const runningLong=t.status==='running'&&t.started_at&&(Date.now()-new Date(t.started_at).getTime())>t.duration*60000;el.classList.toggle('running-long',runningLong);if(t.escalated&&!h3.querySelector('.escalated-chip')){const chip=document.createElement('span');chip.className='chip state-chip escalated-chip';chip.textContent='⚠ Escalated';if(t.escalation_reason)chip.title=t.escalation_reason;h3.appendChild(chip)}if(t.incident&&!h3.querySelector('.incident-chip')){const chip=document.createElement('span');chip.className='chip state-chip incident-chip';chip.textContent='🔥 Incident';if(t.incident_reason)chip.title=t.incident_reason;h3.appendChild(chip)}if(runningLong&&!h3.querySelector('.running-long-chip')){const chip=document.createElement('span');chip.className='chip state-chip running-long-chip';chip.textContent='⏱ Running long';h3.appendChild(chip)}const actions=el.querySelector('.task-actions');if(actions&&t.status!=='complete'&&t.status!=='skipped'&&!actions.querySelector('.escalate-btn')){const escBtn=document.createElement('button');escBtn.className='escalate-btn';escBtn.title=t.escalated?'Clear escalation':'Escalate this task';escBtn.textContent=t.escalated?'⚠ Clear':'⚠ Escalate';escBtn.onclick=()=>toggleEscalate(t.id,!t.escalated);const incBtn=document.createElement('button');incBtn.className='incident-btn';incBtn.title=t.incident?'Clear incident flag':'Flag as incident-causing';incBtn.textContent=t.incident?'🔥 Clear':'🔥 Incident';incBtn.onclick=()=>toggleIncident(t.id,!t.incident);actions.append(escBtn,incBtn)}})};
const ctaskRenderDetail=renderDetail;
renderDetail=function(){ctaskRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot||!r)return;$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];if(!t||!t.serviceops_ctask)return;const h3=el.querySelector('h3');if(h3&&!h3.querySelector('.ctask-chip')){const chip=document.createElement('span');chip.className='chip ctask-chip';chip.textContent=t.serviceops_ctask;h3.appendChild(chip)}const small=el.querySelector('small');if(small&&!small.querySelector('.ctask-meta')){const meta=document.createElement('span');meta.className='ctask-meta';meta.textContent=` · ${t.serviceops_ctask_team||'No team'} · ${t.owner||'Unassigned'}`;small.appendChild(meta)}});const soCard=$$('.detail-side .panel').find(c=>c.querySelector('h2')&&c.querySelector('h2').textContent==='ServiceOps record');if(soCard&&!soCard.querySelector('.ctask-subtasks')){const ctasks=(r.tasks||[]).filter(t=>t.serviceops_ctask);if(ctasks.length){const wrap=document.createElement('div');wrap.className='ctask-subtasks';wrap.innerHTML=`<h3 style="margin:14px 0 6px;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">Sub-tasks</h3>`+ctasks.map(t=>`<div class="kv"><span>${esc(t.serviceops_ctask)} · ${esc(t.title)}</span><b>${esc(t.serviceops_ctask_team||'No team')} · ${esc(t.owner||'Unassigned')}</b></div>`).join('');soCard.appendChild(wrap)}}};
function parsePairs(text){const out={};(text||'').split(',').forEach(pair=>{const idx=pair.indexOf('=');if(idx<0)return;const k=pair.slice(0,idx).trim(),v=pair.slice(idx+1).trim();if(k)out[k]=v});return out}
function formatPairs(obj){return Object.entries(obj||{}).map(([k,v])=>`${k}=${v}`).join(', ')}
const contextRenderDetail=renderDetail;
renderDetail=function(){contextRenderDetail();const r=state.current,side=$('.detail-side');if(!side||!can('runbooks:edit'))return;if(side.querySelector('.automation-context-card'))return;const context=r.automation_context||{headers:{},variables:{}};const hasContext=Object.keys(context.headers||{}).length||Object.keys(context.variables||{}).length;const card=document.createElement('article');card.className='panel sidecard automation-context-card';card.innerHTML=`<div class="panelhead"><div><h2>Automation context</h2><p>Extra headers and {{variables}} applied to every automation task in this runbook</p></div><button class="secondary" id="editAutomationContext">✎ Edit</button></div>${hasContext?`<div class="kv"><span>Headers</span><b>${esc(formatPairs(context.headers))||'—'}</b></div><div class="kv"><span>Variables</span><b>${esc(formatPairs(context.variables))||'—'}</b></div>`:'<p class="muted">No context configured yet.</p>'}`;side.append(card);$('#editAutomationContext').onclick=async()=>{const r2=await formDialog({eyebrow:'AUTOMATION CONTEXT',title:'Edit automation context',submitLabel:'Save',fields:[{name:'headers',label:'Extra headers',value:formatPairs(context.headers),hint:'Name=value, comma-separated'},{name:'variables',label:'Variables',value:formatPairs(context.variables),hint:'For {{var}} substitution in automation URLs — name=value, comma-separated'}]});if(!r2)return;try{state.current=await api(`/api/runbooks/${r.id}`,{method:'PATCH',body:JSON.stringify({automation_context:{headers:parsePairs(r2.headers),variables:parsePairs(r2.variables)}})});renderDetail();toast('Automation context updated')}catch(e){toast(e.message,true)}}};
const testFireRenderDetail=renderDetail;
renderDetail=function(){testFireRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot||!r||!can('runbooks:edit'))return;$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];if(!t||t.task_type!=='automation'||!t.automation_url)return;const actionsEl=el.querySelector('.task-actions');if(!actionsEl||actionsEl.querySelector('.test-fire-btn'))return;const btn=document.createElement('button');btn.className='test-fire-btn';btn.textContent='🧪 Test';btn.title='Fire this automation URL without changing the task\'s status';btn.onclick=async()=>{btn.disabled=true;btn.textContent='Testing…';try{const result=await api(`/api/tasks/${t.id}/test-fire`,{method:'POST',body:'{}'});toast(result.ok?'Test fire succeeded':'Test fire failed: '+(result.result||''),!result.ok)}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent='🧪 Test'}};actionsEl.appendChild(btn)})};
const servicenowRenderDetail=renderDetail;
renderDetail=function(){servicenowRenderDetail();const r=state.current,side=$('.detail-side');if(!side||!can('runbooks:edit'))return;if(side.querySelector('.servicenow-card'))return;const card=document.createElement('article');card.className='panel sidecard servicenow-card';card.innerHTML=`<div class="panelhead"><div><h2>ServiceNow change</h2><p>${r.servicenow_change_number?'REST Table API · last sync '+fmt(r.servicenow_synced_at):'Not linked'}</p></div><button class="secondary" id="linkServicenow">${r.servicenow_change_number?'⇄ Sync':'⇄ Link'}</button></div>${r.servicenow_change_number?`<div class="kv"><span>Number</span><b>${esc(r.servicenow_change_number)}</b></div><div class="kv"><span>State</span><b>${esc(r.servicenow_state||'—')}</b></div>`:'<p class="muted">Link a ServiceNow change_request number to sync its state with this runbook.</p>'}`;side.append(card);$('#linkServicenow').onclick=async()=>{const r2=await formDialog({eyebrow:'SERVICENOW',title:'Link a ServiceNow change',submitLabel:'Sync',fields:[{name:'ticket',label:'Change number',value:r.servicenow_change_number||'',required:true,placeholder:'e.g. CHG0001234'}]});if(!r2||!r2.ticket)return;try{const result=await api(`/api/runbooks/${r.id}/servicenow-sync`,{method:'POST',body:JSON.stringify({ticket:r2.ticket})});state.current=result;renderDetail();toast(`Synced ${result.servicenow_change_number}`)}catch(e){toast(e.message,true)}}};
const topbarPopoverStyles=`.topbar-popover{position:fixed;z-index:45;width:min(320px,calc(100% - 28px));max-height:calc(100vh - 90px);background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 22px 60px #18203c2c;overflow:hidden;transform:translateY(-8px) scale(.98);opacity:0;pointer-events:none;transition:.16s}.topbar-popover.open{transform:none;opacity:1;pointer-events:auto}.topbar-popover-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid var(--line)}.topbar-popover-head h2{font-size:13px;margin:0}.topbar-popover-list{max-height:340px;overflow:auto;padding:6px}.topbar-popover-item{display:block;width:100%;text-align:left;border:0;background:transparent;padding:9px 10px;border-radius:8px;font-size:12.5px;color:var(--ink)}.topbar-popover-item:hover{background:#f5f6fa}.topbar-popover-empty{padding:26px 18px;text-align:center;color:var(--muted);font-size:12.5px}.topbar-popover-help p{margin:0 0 10px;font-size:12.5px;color:var(--ink);line-height:1.5}.topbar-popover-help{padding:14px 16px}`;
document.head.append(Object.assign(document.createElement('style'),{textContent:topbarPopoverStyles}));
function openTopbarPopover(anchor,{title,bodyHtml}){$$('.topbar-popover').forEach(p=>p.remove());const pop=document.createElement('div');pop.className='topbar-popover';pop.innerHTML=`<div class="topbar-popover-head"><h2>${esc(title)}</h2><button type="button" class="gd-close" aria-label="Close">×</button></div>${bodyHtml}`;document.body.append(pop);const rect=anchor.getBoundingClientRect();pop.style.top=`${rect.bottom+8}px`;pop.style.right=`${Math.max(12,window.innerWidth-rect.right-6)}px`;requestAnimationFrame(()=>pop.classList.add('open'));const close=()=>{pop.classList.remove('open');setTimeout(()=>pop.remove(),160);document.removeEventListener('click',onDoc,true)};const onDoc=e=>{if(!pop.contains(e.target)&&e.target!==anchor)close()};pop.querySelector('.gd-close').onclick=close;setTimeout(()=>document.addEventListener('click',onDoc,true),0);return{close}}
function favoriteRunbookIds(){try{return JSON.parse(localStorage.getItem('flowops_favorites')||'[]')}catch(_){return[]}}
function setFavoriteRunbookIds(ids){try{localStorage.setItem('flowops_favorites',JSON.stringify(ids))}catch(_){}}
function isRunbookFavorited(id){return favoriteRunbookIds().includes(id)}
function toggleFavoriteRunbook(id){const ids=favoriteRunbookIds();const next=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];setFavoriteRunbookIds(next);return next.includes(id)}
function recentRunbooks(){try{return JSON.parse(localStorage.getItem('flowops_recent')||'[]')}catch(_){return[]}}
function pushRecentRunbook(id,name){const list=recentRunbooks().filter(r=>r.id!==id);list.unshift({id,name,at:Date.now()});try{localStorage.setItem('flowops_recent',JSON.stringify(list.slice(0,8)))}catch(_){}}
const recentTrackOpenRunbook=openRunbook;openRunbook=async function(id,opts={}){await recentTrackOpenRunbook(id,opts);if(state.current&&state.current.id===id)pushRecentRunbook(id,state.current.name)};
$('#favoritesBtn').onclick=()=>{const ids=favoriteRunbookIds();const known=state.runbooks||[];const items=ids.map(id=>known.find(r=>r.id===id)).filter(Boolean);openTopbarPopover($('#favoritesBtn'),{title:'Favorites',bodyHtml:items.length?`<div class="topbar-popover-list">${items.map(r=>`<button type="button" class="topbar-popover-item" data-open-fav="${r.id}">☆ ${esc(r.name)}</button>`).join('')}</div>`:'<div class="topbar-popover-empty">No favorites yet.<br>Star a runbook from its detail page to add it here.</div>'});$$('[data-open-fav]').forEach(b=>b.onclick=()=>{openRunbook(Number(b.dataset.openFav));$$('.topbar-popover').forEach(p=>p.remove())})};
$('#recentBtn').onclick=()=>{const items=recentRunbooks();openTopbarPopover($('#recentBtn'),{title:'Recently viewed',bodyHtml:items.length?`<div class="topbar-popover-list">${items.map(r=>`<button type="button" class="topbar-popover-item" data-open-recent="${r.id}">${esc(r.name)}</button>`).join('')}</div>`:'<div class="topbar-popover-empty">Runbooks you open will appear here.</div>'});$$('[data-open-recent]').forEach(b=>b.onclick=()=>{openRunbook(Number(b.dataset.openRecent));$$('.topbar-popover').forEach(p=>p.remove())})};
$('#helpBtn').onclick=()=>{openTopbarPopover($('#helpBtn'),{title:'Help',bodyHtml:'<div class="topbar-popover-help"><p><b>Keyboard:</b> Enter opens a focused runbook row; Escape closes any open menu or dialog.</p><p><b>Runbooks:</b> use the ⋯ More menu on a runbook for sync, export, snippets, templates and deletion.</p><p>Need more help? Contact your workspace administrator.</p></div>'})};
$('#settingsShortcut').onclick=()=>{if(can('admin:access'))show('admin');else toast('Administrator access required',true)};
const favoriteRenderDetail=renderDetail;renderDetail=function(){favoriteRenderDetail();const r=state.current,menu=$('.more-menu');if(!menu||$('#toggleFavorite'))return;const btn=document.createElement('button');btn.type='button';btn.id='toggleFavorite';const setLabel=()=>{btn.textContent=isRunbookFavorited(r.id)?'★ Remove from favorites':'☆ Add to favorites'};setLabel();btn.onclick=()=>{toggleFavoriteRunbook(r.id);setLabel()};menu.prepend(btn)};
function updateWorkspaceClock(){
  const tz=(state.settings&&state.settings.timezone)||'UTC';
  try{
    const now=new Date();
    if($('#todayLabel'))$('#todayLabel').textContent=new Intl.DateTimeFormat('en-US',{timeZone:tz,weekday:'long',month:'long',day:'numeric'}).format(now).toUpperCase();
    if($('#lastUpdated'))$('#lastUpdated').textContent=`· Last updated ${new Intl.DateTimeFormat('en-US',{timeZone:tz,hour:'2-digit',minute:'2-digit',hour12:false,timeZoneName:'short'}).format(now)}`;
  }catch(_){}
}
const clockTrackedLoad=load;load=async function(){await clockTrackedLoad();updateWorkspaceClock()};
setInterval(updateWorkspaceClock,60000);
boot();
